typedef unsigned int size_t;
typedef int ptrdiff_t;

inline void* operator new(size_t, void* p) { return p; }

class my_alloc
{
public:
  static void* allocate(size_t);
  static void deallocate(void*, size_t);
};

template<class T>
class my_allocator
{
public:
  typedef T* pointer;
  typedef const T* const_pointer;
  typedef T& reference;
  typedef const T& const_reference;
  typedef size_t size_type;
  typedef ptrdiff_t difference_type;

  pointer allocate(size_type n) { return (pointer)my_alloc::allocate(n * sizeof(T)); }
  void deallocate(pointer p, size_type n) { my_alloc::deallocate(p, n * sizeof(T)); }
  void construct(pointer p, const_reference x) { new(p) T(x); }
  void destroy(pointer p) { p->~T(); }
};

class morphable_item_range;

template<class T, class Alloc>
class vector
{
public:
  typedef T* iterator;
  typedef size_t size_type;

  iterator _M_start;
  iterator _M_finish;
  iterator _M_end_of_storage;
  Alloc _M_allocator;

  void _M_insert_aux(iterator position, const T& x);
};

template<class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T& x)
{
  if (_M_finish != _M_end_of_storage)
  {
    _M_allocator.construct(_M_finish, *(_M_finish - 1));
    ++_M_finish;
    T x_copy = x;
    T* first = position;
    T* last = _M_finish - 2;
    T* result = _M_finish - 1;
    while (first != last)
      *--result = *--last;
    *position = x_copy;
  }
  else
  {
    const size_type old_size = _M_finish - _M_start;
    const size_type len = old_size != 0 ? 2 * old_size : 1;
    iterator new_start = _M_allocator.allocate(len);
    iterator new_finish = new_start;
    for (iterator i = _M_start; i != position; ++i, ++new_finish)
      _M_allocator.construct(new_finish, *i);
    _M_allocator.construct(new_finish, x);
    ++new_finish;
    for (iterator i = position; i != _M_finish; ++i, ++new_finish)
      _M_allocator.construct(new_finish, *i);
    for (iterator i = _M_start; i != _M_finish; ++i)
      _M_allocator.destroy(i);
    _M_allocator.deallocate(_M_start, _M_end_of_storage - _M_start);
    _M_start = new_start;
    _M_finish = new_finish;
    _M_end_of_storage = new_start + len;
  }
}

template void vector<morphable_item_range*, my_allocator<morphable_item_range*> >::_M_insert_aux(
  morphable_item_range**, morphable_item_range* const&);
